-- AIRA Prospect Profiling Platform — v1 schema (demo-first, permissive RLS)\n-- Core tables only. Secondary tables (audit_logs, tasks) added in later sprints.\n\ncreate table if not exists prospects (\n  id uuid primary key default gen_random_uuid(),\n  user_id uuid,\n  name text not null,\n  contact_info text,\n  source text,\n  cultural_background text,\n  budget_range text,\n  status text not null default 'new',\n  created_at timestamptz not null default now()\n);\nalter table prospects enable row level security;\ndrop policy if exists \"prospects_v1_read\" on prospects;\ncreate policy \"prospects_v1_read\" on prospects for select using (true);\ndrop policy if exists \"prospects_v1_write\" on prospects;\ncreate policy \"prospects_v1_write\" on prospects for all using (true) with check (true);\n\ncreate table if not exists interactions (\n  id uuid primary key default gen_random_uuid(),\n  user_id uuid,\n  prospect_id uuid not null references prospects(id) on delete cascade,\n  consultant_name text,\n  interaction_type text,\n  personality_observations text,\n  intentions text,\n  objections text,\n  lifestyle_notes text,\n  mood_after text,\n  created_at timestamptz not null default now()\n);\nalter table interactions enable row level security;\ndrop policy if exists \"interactions_v1_read\" on interactions;\ncreate policy \"interactions_v1_read\" on interactions for select using (true);\ndrop policy if exists \"interactions_v1_write\" on interactions;\ncreate policy \"interactions_v1_write\" on interactions for all using (true) with check (true);\n\ncreate table if not exists prospect_profiles (\n  id uuid primary key default gen_random_uuid(),\n  user_id uuid,\n  prospect_id uuid not null references prospects(id) on delete cascade,\n  summary text,\n  socio_economic jsonb,\n  investment_objectives jsonb,\n  behavioral_tendencies jsonb,\n  lifestyle_aspirations jsonb,\n  motivations jsonb,\n  source text,\n  confidence numeric,\n  review_status text not null default 'unreviewed',\n  created_at timestamptz not null default now()\n);\nalter table prospect_profiles enable row level security;\ndrop policy if exists \"prospect_profiles_v1_read\" on prospect_profiles;\ncreate policy \"prospect_profiles_v1_read\" on prospect_profiles for select using (true);\ndrop policy if exists \"prospect_profiles_v1_write\" on prospect_profiles;\ncreate policy \"prospect_profiles_v1_write\" on prospect_profiles for all using (true) with check (true);\n\ncreate table if not exists strategies (\n  id uuid primary key default gen_random_uuid(),\n  user_id uuid,\n  prospect_id uuid not null references prospects(id) on delete cascade,\n  profile_id uuid references prospect_profiles(id) on delete set null,\n  pitch_angle text,\n  talking_points jsonb,\n  closing_technique text,\n  cultural_considerations text,\n  source text,\n  confidence numeric,\n  review_status text not null default 'unreviewed',\n  created_at timestamptz not null default now()\n);\nalter table strategies enable row level security;\ndrop policy if exists \"strategies_v1_read\" on strategies;\ncreate policy \"strategies_v1_read\" on strategies for select using (true);\ndrop policy if exists \"strategies_v1_write\" on strategies;\ncreate policy \"strategies_v1_write\" on strategies for all using (true) with check (true);\n\n-- Seed data\ninsert into prospects (name, contact_info, source, cultural_background, budget_range, status) values\n('Tan Sri Rahman', '012-3456789', 'referral', 'Malay', '3M-5M MYR', 'negotiating'),\n('Lim Wei', '011-9876543', 'walk-in', 'Malay-Chinese', '2M-3M MYR', 'engaged'),\n('Priya Krishnan', '013-5551234', 'social', 'Malay-Indian', '1.5M-2.5M MYR', 'new'),\n('Zhang Jie', '019-2223344', 'press', 'Mainland Chinese', '3M-6M MYR', 'engaged'),\n('Ahmad Faizal', '016-7778899', 'referral', 'Malay', '2M-4M MYR', 'new')\non conflict do nothing;\n\ninsert into interactions (prospect_id, consultant_name, interaction_type, personality_observations, intentions, objections, lifestyle_notes, mood_after) values\n((select id from prospects where name = 'Tan Sri Rahman'), 'Sara', 'meeting', 'Confident, status-conscious, values relationships', 'Primary residence for family', 'Concerned about maintenance fees', 'Wants exclusive facilities, privacy', 'positive'),\n((select id from prospects where name = 'Tan Sri Rahman'), 'Sara', 'call', 'Follows through on commitments', 'Wants to move before school year', 'Needs wife approval', 'School proximity matters', 'positive'),\n((select id from prospects where name = 'Lim Wei'), 'Daniel', 'meeting', 'Analytical, detail-oriented, asks many questions', 'Investment for children education fund', 'Comparing with competitor pricing per sqft', 'Values rental yield and location growth', 'neutral'),\n((select id from prospects where name = 'Zhang Jie'), 'Sara', 'site-visit', 'Impressed by show unit, decisive', 'Investment + occasional stay', 'Concerned about foreign ownership rules', 'Prefers high floor, city view', 'positive')\non conflict do nothing;\n\ninsert into prospect_profiles (prospect_id, summary, socio_economic, investment_objectives, behavioral_tendencies, lifestyle_aspirations, motivations, source, confidence, review_status) values\n((select id from prospects where name = 'Tan Sri Rahman'), 'High-net-worth Malay buyer seeking primary residence with status and family legacy. Relationship-driven, responds to exclusivity messaging.', '{\"tier\": \"high-net-worth\", \"indicators\": [\"budget 3-5M MYR\", \"referral network\"]}', '[\"primary residence\", \"family legacy\", \"exclusive lifestyle\"]', '[\"relationship-driven\", \"status-conscious\", \"decisive when trust established\"]', '[\"exclusive facilities\", \"privacy\", \"school proximity\"]', '[\"security for family\", \"social status\"]', 'demo-seed', 0.78, 'approved')\non conflict do nothing;\n\ninsert into strategies (prospect_id, profile_id, pitch_angle, talking_points, closing_technique, cultural_considerations, source, confidence, review_status) values\n((select id from prospects where name = 'Tan Sri Rahman'), (select id from prospect_profiles where prospect_id = (select id from prospects where name = 'Tan Sri Rahman') limit 1), 'Position AIRA Residence as an exclusive legacy home that signals success and provides a secure, private environment for his family.', '[\"Emphasize exclusive facilities and privacy features\", \"Highlight proximity to top schools\", \"Show limited-unit availability to create urgency\", \"Reference other prominent Malay families in residence\"]', 'Relationship-first close: arrange a private dinner with management to build trust before final decision. Soft, no-pressure approach.', 'Respect Islamic finance sensibilities — avoid alcohol-adjacent imagery. Emphasize family and community. Build trust through personal relationship, not just transaction.', 'demo-seed', 0.74, 'approved')\non conflict do nothing;\n